source("pre.R")
df <- data.frame(a = c(3L, 1L, NA, 1L, 2L), s = c("x", "y", "x", "y", NA), f = c(1.5, NA, NaN, 1.5, 0), e = factor(c("u", "v", "u", NA, "v")), d = as.Date("2020-01-01") + c(0:3, NA))
x <- as_zutable(df)
chk <- function(label, a, b) {
  va <- tryCatch({ if (is_zutable(a)) { schema(a); as.data.frame(a) } else a }, error = function(e) paste("INVALID:", conditionMessage(e)))
  rownames_reset <- function(d) { if (is.data.frame(d)) rownames(d) <- NULL; d }
  ok <- isTRUE(all.equal(rownames_reset(va), rownames_reset(b), check.attributes = FALSE))
  cat(if (ok) "ok  " else "DIFF", label, "| class:", class(a)[1], "\n"); if (!ok) { print(va); print(b) }
}
chk("head", head(x, 2), head(df, 2)); chk("tail", tail(x, 2), tail(df, 2)); chk("head -1", head(x, -1), head(df, -1))
chk("subset", subset(x, a > 1), subset(df, a > 1)); chk("subset sel", subset(x, a > 1, select = c(a, s)), subset(df, a > 1, select = c(a, s))); chk("subset -", subset(x, select = -a), subset(df, select = -a))
chk("unique", unique(x[, c("a", "s")]), unique(df[, c("a", "s")])); chk("duplicated", duplicated(x), duplicated(df))
chk("na.omit", try_(na.omit(x)), na.omit(df)); chk("complete.cases", complete.cases(x), complete.cases(df))
chk("transform", try_(transform(x, a = a + 1L)), transform(df, a = a + 1L)); chk("transform new", try_(transform(x, z = a + 1L)), transform(df, z = a + 1L))
chk("within", try_(within(x, a <- a * 2L)), within(df, a <- a * 2L)); chk("with", with(x, sum(a, na.rm = TRUE)), with(df, sum(a, na.rm = TRUE)))
sp <- try_(split(x, x$s)); spd <- split(df, df$s); for (n in names(spd)) chk(paste("split", n), sp[[n]], spd[[n]])
chk("order idx", x[order(x$a), ], df[order(df$a), ]); chk("rev rows", x[nrow(x):1, ], df[nrow(df):1, ])
chk("lapply", lapply(x, class), lapply(df, class)); chk("sapply", sapply(x, typeof), sapply(df, typeof)); chk("dim", dim(x), dim(df)); chk("nrow", nrow(x), nrow(df)); chk("names", names(x), names(df)); chk("colnames", colnames(x), colnames(df))
chk("summary", try_(summary(x)), summary(df)); chk("str", capture.output(str(as.data.frame(x))), capture.output(str(df)))
chk("aggregate", try_(aggregate(f ~ s, data = x, FUN = sum)), aggregate(f ~ s, data = df, FUN = sum)); chk("tapply", tapply(x$f, x$s, sum), tapply(df$f, df$s, sum))
chk("merge", try_(merge(x, x[, c("a", "s")], by = "a")), merge(df, df[, c("a", "s")], by = "a"))
chk("as.list", as.list(x), as.list(df)); chk("as.matrix", try_(as.matrix(x[, c("a", "f")])), as.matrix(df[, c("a", "f")])); chk("t", try_(t(x[, c("a", "f")])), t(df[, c("a", "f")]))
chk("model", try_(coef(lm(f ~ a, data = x))), coef(lm(f ~ a, data = df))); chk("stack", try_(stack(x[, c("a", "f")])), stack(df[, c("a", "f")]))
chk("is.na", try_(is.na(x)), is.na(df)); chk("x == 1", try_(x[, c("a","f")] == 1), df[, c("a","f")] == 1); chk("Reduce", try_(do.call(rbind, list(x, x))), rbind(df, df))
chk("cbind", try_(cbind(x, z = 1)), cbind(df, z = 1)); chk("data.frame()", try_(data.frame(x, z = 1)), data.frame(df, z = 1)); chk("sort_by", try_(sort_by(x, ~a)), sort_by(df, ~a))
chk("x[[i,j]]", try_(x[[2, "s"]]), df[[2, "s"]]); chk("x[2, 's']", try_(x[2, "s"]), df[2, "s", drop = FALSE]); chk("x[['a']]", x[["a"]], df[["a"]]); chk("x[[1]]", x[[1]], df[[1]])
chk("dimnames", dimnames(x), dimnames(df)); chk("row.names", row.names(x), row.names(df)); chk("rownames<-", try_({y <- x; rownames(y) <- letters[1:5]; rownames(y)}), as.character(1:5))
chk("rapply/mapply", mapply(function(a, b) paste(a, b), x$a, x$s), mapply(function(a, b) paste(a, b), df$a, df$s))
chk("unsplit", try_(unsplit(split(x, x$e), x$e)), unsplit(split(df, df$e), df$e)); chk("rev", try_(rev(x)), rev(df)); chk("x[-1]", try_(x[-1]), df[-1, ]); chk("droplevels", try_(droplevels(x)), droplevels(df)); chk("by()", try_(unclass(by(x, x$s, function(d) nrow(d)))), unclass(by(df, df$s, function(d) nrow(d))))
chk("apply", try_(apply(x[, c("a", "f")], 1, sum)), apply(df[, c("a", "f")], 1, sum)); chk("format", try_(format(x)), format(df)); chk("all.equal", try_(all.equal(x, x)), TRUE); chk("identical copy", identical(as.data.frame(copy(x)), as.data.frame(x)), TRUE)
chk("xtfrm/order(x)", try_(do.call(order, x)), do.call(order, df)); chk("Filter", try_(Filter(is.numeric, x)), Filter(is.numeric, df)); chk("x[sapply]", try_(x[, sapply(x, is.numeric)]), df[, sapply(df, is.numeric)])
chk("edit in base fn", try_({y <- copy(x); y <- replace(y, 1, list(9L)); y}), replace(df, 1, list(9L)))
chk("is.na<-", try_({y <- copy(x); is.na(y$f) <- 1; y}), {d2 <- df; is.na(d2$f) <- 1; d2}); chk("levels<-", try_({y <- copy(x); levels(y$e) <- c("U", "V"); y}), {d2 <- df; levels(d2$e) <- c("U", "V"); d2})
chk("modifyList", try_(modifyList(x, list(a = 1:5))), modifyList(df, list(a = 1:5))); chk("within NULL", try_(within(x, rm(a))), within(df, rm(a)))
chk("x[order(a)] 1 arg", try_(x[order(x$a)]), df[order(df$a), ])
chk("x[x$a > 1, ]", try_(x[x$a > 1, ]), df[which(df$a > 1), ]); chk("x[x$a > 1]", try_(x[x$a > 1]), df[which(df$a > 1), ]); chk("x[a > 1]", try_(x[a > 1]), df[which(df$a > 1), ]); chk("x[which(a>1)]", try_(x[which(a > 1)]), df[which(df$a > 1), ])
chk("x[!is.na(s)]", try_(x[!is.na(s)]), df[!is.na(df$s), ]); chk("x[is.na(f)]", try_(x[is.na(f)]), df[2, ])
